import express from 'express';
import { logger } from './logger.js';

export const app = express();

// Request logging: one line per completed request.
app.use((req, res, next) => {
  const start = process.hrtime.bigint();
  res.on('finish', () => {
    const ms = Number(process.hrtime.bigint() - start) / 1e6;
    logger.info(
      `${req.method} ${req.originalUrl} ${res.statusCode} ${ms.toFixed(1)}ms`,
    );
  });
  next();
});

app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ ok: true });
});

// Error-handling middleware (4 args, registered last). Express 5 also routes
// rejected promises from async handlers here.
app.use((err, req, res, next) => {
  logger.error(`Unhandled error on ${req.method} ${req.originalUrl}`, err);
  if (res.headersSent) return next(err);
  const status = err.status ?? err.statusCode ?? 500;
  res.status(status).json({ error: status >= 500 ? 'Internal Server Error' : err.message });
});

