import { test } from 'node:test';
import assert from 'node:assert/strict';
import express from 'express';
import { logger } from '../src/logger.js';

test('unhandled async errors are logged and return 500', async (t) => {
  const errors = [];
  t.mock.method(logger, 'error', (msg, err) => errors.push({ msg, err }));
  t.mock.method(logger, 'info', () => {});
  const { app } = await import('../src/app.js');

  // Insert a failing route ahead of the error handler by using a sub-app.
  const wrapper = express();
  wrapper.get('/boom', async () => {
    throw new Error('boom');
  });
  wrapper.use(app);
  // Error handler lives in `app`, so route the failure through it.
  app.get('/boom', async () => {
    throw new Error('boom');
  });

  const server = app.listen(0);
  const { port } = server.address();
  const r = await fetch(`http://127.0.0.1:${port}/boom`);
  server.close();
  assert.equal(r.status, 500);
  assert.equal(errors.length, 1);
  assert.equal(errors[0].err.message, 'boom');
});

